(function () {
  if (window.__consentInit) return; // head scripts can be re-rendered on client navigation
  window.__consentInit = true;
  var TAG_ID = 'G-XXXXXXXXXX'; // your Google tag ID
  var NONCE = (document.currentScript && document.currentScript.nonce) || '';
  var w = window;
  w.dataLayer = w.dataLayer || [];
  function gtag() { w.dataLayer.push(arguments); }
  var TYPES = ['ad_storage', 'analytics_storage', 'ad_user_data', 'ad_personalization'];
  function state(v) { var o = {}; TYPES.forEach(function (t) { o[t] = v; }); return o; }
  gtag('consent', 'default', state('denied')); // before any Google tag request
  function stored() { var m = document.cookie.match(/(?:^|; )consent=(granted|denied)/); return m ? m[1] : null; }
  function store(v) {
    document.cookie = 'consent=' + v + '; Max-Age=31536000; Path=/; SameSite=Lax' + (location.protocol === 'https:' ? '; Secure' : '');
  }
  var loaded = false;
  function loadTag() {
    if (loaded) return;
    loaded = true;
    var s = document.createElement('script');
    s.async = true;
    if (NONCE) s.nonce = NONCE;
    s.src = 'https://www.googletagmanager.com/gtag/js?id=' + encodeURIComponent(TAG_ID);
    document.head.appendChild(s);
    gtag('js', new Date());
    gtag('config', TAG_ID);
  }
  function apply(v) {
    if (v === 'granted') { gtag('consent', 'update', state('granted')); loadTag(); }
    else gtag('consent', 'update', state('denied'));
  }
  var banner = document.getElementById('consent-banner');
  var reopen = document.getElementById('consent-reopen');
  function show(on) { if (banner) banner.hidden = !on; if (reopen) reopen.hidden = on; }
  document.addEventListener('click', function (e) {
    var t = e.target;
    var b = t && t.closest ? t.closest('[data-consent]') : null;
    if (b) { var v = b.getAttribute('data-consent'); store(v); apply(v); show(false); }
    else if (t && t.closest && t.closest('#consent-reopen')) show(true);
  });
  var prior = stored();
  if (prior) { apply(prior); show(false); }
  else { if (navigator.globalPrivacyControl === true) apply('denied'); show(true); }
})();

