import type { ReactNode } from 'react'
import { HeadContent, Link, Outlet, Scripts, createRootRoute } from '@tanstack/react-router'

function NotFoundPage() {
  return (
    <section>
      {/* React 19 hoists <meta> into <head> */}
      <meta name="robots" content="noindex" />
      <h1>Page not found</h1>
      <p>We could not find that page.</p>
      <p><Link to="/">Back to the home page</Link></p>
    </section>
  )
}

function ErrorPage() {
  // Generic text only: never print error.message/stack. Status (500) is set by the router, not here.
  return (
    <section>
      <meta name="robots" content="noindex" />
      <h1>Something went wrong</h1>
      <p>Please try again in a moment.</p>
      <p><a href="/">Back to the home page</a></p>
    </section>
  )
}

function RootShell({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <head>
        <HeadContent />
      </head>
      <body>
        <header>
          <nav aria-label="Main">
            <Link to="/">Home</Link> <Link to="/posts">Posts</Link>
          </nav>
        </header>
        <main>{children}</main>
        <footer><Link to="/privacy">Privacy</Link></footer>
        <Scripts />
      </body>
    </html>
  )
}

export const Route = createRootRoute({
  head: () => ({
    meta: [
      { charSet: 'utf-8' },
      { name: 'viewport', content: 'width=device-width, initial-scale=1' },
      { title: 'Example' },
    ],
  }),
  shellComponent: RootShell,
  component: Outlet,
  notFoundComponent: NotFoundPage,
  errorComponent: ErrorPage,
