import { createFileRoute, notFound } from '@tanstack/react-router'
import { createServerFn } from '@tanstack/react-start'
import { db } from '../server/db' // placeholder DB client

const getPost = createServerFn({ method: 'GET' })
  .validator((slug: string) => slug)
  .handler(async ({ data: slug }) => {
    // A DB outage throws here: leave it uncaught so the router answers 5xx, not 404/200.
    return (await db.posts.findBySlug(slug)) ?? null
  })

export const Route = createFileRoute('/posts/$postId')({
  loader: async ({ params }) => {
    const post = await getPost({ data: params.postId }) // unknown or probe values (sg-probe-404) -> null
    if (!post) throw notFound() // decided in the loader, before any streaming starts -> real 404
    return post
  },
  component: () => {
    const post = Route.useLoaderData()
    return <article><h1>{post.title}</h1></article>
  },
})

