import { createMiddleware } from '@tanstack/react-start'

const RETIRED = new Set(['/old-offer', '/2019-campaign'])

export const retiredMiddleware = createMiddleware().server(({ next, request }) => {
  if (!RETIRED.has(new URL(request.url).pathname)) return next()
  const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex"><title>Gone</title></head>
<body><header><nav aria-label="Main"><a href="/">Home</a> <a href="/posts">Posts</a></nav></header>
<main><h1>This page has been removed</h1><p><a href="/">Back to the home page</a></p></main></body></html>`
  return new Response(html, { status: 410, headers: { 'Content-Type': 'text/html; charset=utf-8' } })
})

TanStack Start 1.x. Plain HTML form posting to a server route in the same file as the page, so it works without JavaScript (303 on success, 502 page on delivery failure). Cross-site writes are rejected by Start's createCsrfMiddleware (Origin/Sec-Fetch-Site/Referer, 403). The in-memory limiter is a placeholder for Redis/Upstash; behind a proxy only trust x-forwarded-for if the proxy sets it.
