import { createFileRoute } from '@tanstack/react-router'
import { createCsrfMiddleware } from '@tanstack/react-start'
import appCss from '../styles/app.css?url' // must define .hp { position: absolute; left: -10000px } (no inline styles under the CSP)

const hits = new Map<string, number[]>() // placeholder for Redis/Upstash
const LIMIT = 5
const WINDOW_MS = 10 * 60 * 1000

function tooMany(ip: string): boolean {
  const now = Date.now()
  const recent = (hits.get(ip) ?? []).filter((t) => now - t < WINDOW_MS)
  recent.push(now)
  hits.set(ip, recent)
  return recent.length > LIMIT
}

function page(status: number, message: string): Response {
  const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex"><title>Contact</title></head>
<body><nav aria-label="Main"><a href="/">Home</a> <a href="/contact">Contact</a></nav><main><h1>${message}</h1><p><a href="/contact">Back to the form</a></p></main></body></html>`
  return new Response(html, { status, headers: { 'Content-Type': 'text/html; charset=utf-8' } })
}

export const Route = createFileRoute('/contact')({
  validateSearch: (s: Record<string, unknown>) => ({ sent: s.sent === '1' }),
  head: () => ({ meta: [{ title: 'Contact us' }], links: [{ rel: 'stylesheet', href: appCss }] }),
  server: {
    handlers: ({ createHandlers }) =>
      createHandlers({
        POST: {
          middleware: [createCsrfMiddleware()], // SEC-024: cross-site POST -> 403
          handler: async ({ request }) => {
            const ip = request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown'
            if (tooMany(ip)) return page(429, 'Too many messages, please try again later') // SEC-054/055
            const form = await request.formData()
            if (String(form.get('website') ?? '') !== '') {
              // honeypot filled: same success-looking answer, no side effect
              return new Response(null, { status: 303, headers: { Location: '/contact?sent=1' } })
            }
            const name = String(form.get('name') ?? '').trim()
            const email = String(form.get('email') ?? '').trim()
            const message = String(form.get('message') ?? '').trim()
            if (!name || name.length > 100 || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email) || email.length > 254 || !message || message.length > 5000) {
              return page(400, 'Please check the form and try again')
            }
            try {
              const res = await fetch(process.env.FORM_WEBHOOK_URL!, { // the one line the project replaces (email API / CRM / DB insert)
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ name, email, message }),
                signal: AbortSignal.timeout(8000),
              })
              if (!res.ok) throw new Error(`webhook ${res.status}`)
            } catch {
              return page(502, 'Your message could not be sent. Please try again later') // never a success message on failure
            }
            return new Response(null, { status: 303, headers: { Location: '/contact?sent=1' } }) // PRG
          },
        },
      }),
  },
  component: ContactPage,
})

function ContactPage() {
  const { sent } = Route.useSearch()
  if (sent) return <p role="status">Thanks, your message was sent.</p>
  return (
    <form method="post" action="/contact">
      <label>Name <input name="name" autoComplete="name" required maxLength={100} /></label>
      <label>Email <input name="email" type="email" autoComplete="email" required maxLength={254} /></label>
      <label>Message <textarea name="message" required maxLength={5000} /></label>
      <div className="hp" aria-hidden="true">
        <label>Website <input name="website" tabIndex={-1} autoComplete="off" /></label>
      </div>
      {/* Cloudflare Turnstile alternative: render the widget and verify cf-turnstile-response server-side */}
      <p>By sending this form you accept our <a href="/privacy">privacy notice</a>.</p>
      <button type="submit">Send</button>
    </form>
  )
}

TanStack Start 1.x (Vite + Node/Nitro). A global request middleware makes a fresh nonce per request and sends the CSP and the other headers; the router receives the same nonce through `ssr.nonce` so Start stamps its own <script>/<style> tags. Defining src/start.ts means you must also list the CSRF middleware (Start only auto-installs it when src/start.ts is absent).
