import { createMiddleware } from '@tanstack/react-start'
import { setResponseHeader } from '@tanstack/react-start/server'

// Hashed assets are static files this middleware never sees: make the host serving the client build send
// 'Cache-Control: public, max-age=31536000, immutable' for the hashed assets dir (CDN/proxy rule; on Nitro set
// maxAge: 31536000 on that public-assets entry). Verify: curl -I https://example.com/assets/<hashed-file>.js

export const securityMiddleware = createMiddleware().server(async ({ next, request }) => {
  // Fresh random nonce for every response (SEC-010, SEC-075).
  const nonce = btoa(String.fromCharCode(...crypto.getRandomValues(new Uint8Array(16))))
  const csp = [
    "default-src 'self'",
    `script-src 'self' 'nonce-${nonce}' 'strict-dynamic'`, // no Google hosts here: the consent loader's tag is trusted via strict-dynamic
    `style-src 'self' 'nonce-${nonce}'`,
    "img-src 'self' data:",
    "font-src 'self'",
    "connect-src 'self'", // analytics beacons (google-analytics.com ...) go here only, see the consent recipe
    "object-src 'none'",
    "base-uri 'self'",
    "form-action 'self'",
    "frame-ancestors 'none'",
    'upgrade-insecure-requests',
  ].join('; ')
  setResponseHeader('Content-Security-Policy', csp)
  setResponseHeader('X-Content-Type-Options', 'nosniff')
  setResponseHeader('Referrer-Policy', 'strict-origin-when-cross-origin')
  setResponseHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=()')
  const url = new URL(request.url)
  if (url.protocol === 'https:' || request.headers.get('x-forwarded-proto') === 'https') {
    setResponseHeader('Strict-Transport-Security', 'max-age=63072000; includeSubDomains')
  }
  // HTML cache policy (PRF-008). Personalised pages must override with 'private, no-store'.
  const wantsHtml = (request.headers.get('accept') ?? '').includes('text/html')
  if (request.method === 'GET' && wantsHtml && !url.pathname.startsWith('/api/')) {
    setResponseHeader('Cache-Control', 'public, max-age=0, must-revalidate')
  }
  return next({ context: { nonce } }) // makes the nonce visible to getRouter() below
})

