import { createRouter } from '@tanstack/react-router'
import { getGlobalStartContext } from '@tanstack/react-start'
import { routeTree } from './routeTree.gen'

function requestNonce(): string | undefined {
  try {
    // Server: context returned by the global middleware. Browser: undefined (SSR tags already carry the nonce).
    return (getGlobalStartContext() as { nonce?: string } | undefined)?.nonce
  } catch {
    return undefined // build/prerender: no request context
  }
}

export function getRouter() {
  return createRouter({
    routeTree,
    ssr: { nonce: requestNonce() }, // HeadContent and Scripts stamp this on every tag they render
  })
}

