import { createFileRoute } from '@tanstack/react-router'
import { db } from '../../server/db' // placeholder: your DB client

const NO_STORE = { 'Cache-Control': 'no-store' } // OPS-002: never cached

async function dbReachable(): Promise<boolean> {
  let timer: ReturnType<typeof setTimeout> | undefined
  try {
    await Promise.race([
      db.query('SELECT 1'),
      new Promise((_, reject) => {
        timer = setTimeout(() => reject(new Error('timeout')), 2000)
      }),
    ])
    return true
  } catch {
    return false // swallow the detail on purpose
  } finally {
    clearTimeout(timer)
  }
}

export const Route = createFileRoute('/api/health')({
  server: {
    handlers: {
      GET: async () =>
        (await dbReachable())
          ? Response.json({ status: 'ok' }, { headers: NO_STORE })
          : Response.json({ status: 'unavailable' }, { status: 503, headers: NO_STORE }),
    },
  },
})

