import { createFileRoute } from '@tanstack/react-router'

export const Route = createFileRoute('/robots.txt')({
  server: {
    handlers: {
      GET: () => {
        const prod = process.env.DEPLOY_ENV === 'production' // the only value that means production
        const site = (process.env.SITE_URL ?? '').replace(/\/+$/, '') // e.g. https://example.com
        const body = prod
          ? `User-agent: *\nAllow: /\nDisallow: /api/\nSitemap: ${site}/sitemap.xml\n` // never Disallow /assets/ or other asset paths
          : 'User-agent: *\nDisallow: /\n' // non-production: no Sitemap line
        return new Response(body, { headers: { 'Content-Type': 'text/plain; charset=utf-8' } })
      },
    },
  },
})

