import { createFileRoute } from '@tanstack/react-router'
import { listIndexablePaths } from '../server/pages' // placeholder: canonical, indexable, public paths only

const esc = (s: string) =>
  s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;')

export const Route = createFileRoute('/sitemap.xml')({
  server: {
    handlers: {
      GET: async () => {
        if (process.env.DEPLOY_ENV !== 'production') return new Response('Not found', { status: 404 })
        const site = (process.env.SITE_URL ?? '').replace(/\/+$/, '')
        const paths = [...new Set(await listIndexablePaths())].slice(0, 50000) // unique; split into a sitemap index above 50,000
        const urls = paths.map((p) => `  <url><loc>${esc(site + p)}</loc></url>`).join('\n') // same trailing-slash policy as the canonical tags
        const xml = `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls}\n</urlset>\n`
        return new Response(xml, { headers: { 'Content-Type': 'application/xml; charset=utf-8' } })
      },
    },
  },
})

